/bin/bash -c "python3 - <<'PY'
from fractions import Fraction as F

def eta(a,b):
    if a == b:
        return F(0)
    if b < a:
        return 1-b/a
    return 1-(1-b)/(1-a)

rates=[F(1,2),F(13,25)]
values={a:sum(eta(a,b) for b in rates)/2 for a in [F(0),F(1),*rates]}
best=min(values.values())
print('Binary special case, exact DCP:',best,'=',float(best))
print('Total variation from original equal-rate distribution:',float((rates[1]-rates[0])/2))

def surrogate(a,b):
    return a*(a-b) if a >= b else (1-a)*(b-a)
p=(F(3,5),F(1,5));q=(F(4,5),F(3,5))
mid=tuple((x+y)/2 for x,y in zip(p,q))
print('Equation 18 midpoint:',float(surrogate(*mid)))
print('Mean of endpoint values:',float((surrogate(*p)+surrogate(*q))/2))

matrices=[
    [[F(0),F(1,2),F(1,2)],[F(3,4),F(0),F(1,4)],[F(3,4),F(1,4),F(0)]],
    [[F(0),F(3,4),F(1,4)],[F(1,2),F(0),F(1,2)],[F(1,4),F(3,4),F(0)]]
]
marginals=[]
for m in matrices:
    assert all(sum(row)==1 for row in m)
    assert all(m[i][i]==0 for i in range(3))
    marg=[sum(m[y][z] for y in range(3))/3 for z in range(3)]
    marginals.append(marg)
    print('Uniform true-label frequencies, zero-diagonal feasible predicted marginal:',list(map(float,marg)))
print('Equation 13 minimized bound: 0; minimum DCP lower bound from marginal TV:',float(sum(abs(a-b) for a,b in zip(*marginals))/4))
PY"
